const body = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body)
    ? $json.body
    : {};
  const AGENT_IDS = ['project-manager', 'sales', 'marketing', 'investment', 'bookkeeping'];
  const enabledSkills = Array.isArray(body.enabledSkills) ? body.enabledSkills : [];
  const globalInstructions =
    typeof body.globalInstructions === 'string' ? body.globalInstructions.trim() : '';
  const agents = body.agents && typeof body.agents === 'object' && !Array.isArray(body.agents)
    ? body.agents
    : {};
  const sourceHash = typeof body.sourceHash === 'string' ? body.sourceHash : '';
  const ids = enabledSkills.map((skill) => skill?.id);
  const uniqueIds = new Set(ids);
  const validSkill = (skill) =>
    skill &&
    typeof skill.id === 'string' &&
    /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(skill.id) &&
    [...AGENT_IDS, 'global'].includes(skill.agent) &&
    typeof skill.name === 'string' &&
    typeof skill.version === 'string' &&
    typeof skill.description === 'string' &&
    typeof skill.instructions === 'string';
  const validAgent = (agent) =>
    agent &&
    Array.isArray(agent.skillIds) &&
    new Set(agent.skillIds).size === agent.skillIds.length &&
    agent.skillIds.every((id) => typeof id === 'string' && ids.includes(id)) &&
    typeof agent.instructions === 'string' &&
    agent.instructions.length <= 200000 &&
    typeof agent.context === 'string' &&
    agent.context.length <= 200000;

  let error = null;
  if (body.schemaVersion !== 2) {
    error = 'The skill bundle schema version is not supported.';
  } else if (
    enabledSkills.length === 0 ||
    !enabledSkills.every(validSkill) ||
    uniqueIds.size !== enabledSkills.length
  ) {
    error = 'The enabled skill list is empty or invalid.';
  } else if (globalInstructions.length > 200000) {
    error = 'Global instructions exceed 200,000 characters.';
  } else if (
    Object.keys(agents).sort().join('|') !== [...AGENT_IDS].sort().join('|') ||
    !AGENT_IDS.every((agentId) => validAgent(agents[agentId]))
  ) {
    error = 'The per-agent skill groups are missing or invalid.';
  } else if (!/^[a-f0-9]{64}$/.test(sourceHash)) {
    error = 'The skill source hash is invalid.';
  } else if (!AGENT_IDS.every((agentId) => {
    const expected = enabledSkills
      .filter((skill) => skill.agent === agentId)
      .map((skill) => skill.id)
      .sort();
    const actual = [...agents[agentId].skillIds].sort();
    return JSON.stringify(expected) === JSON.stringify(actual);
  })) {
    error = 'A skill is assigned to the wrong agent group.';
  } else if (!enabledSkills.every((skill) => {
    const marker = `(${skill.id}@${skill.version})`;
    return skill.agent === 'global'
      ? AGENT_IDS.every((agentId) => agents[agentId].instructions.includes(marker))
      : agents[skill.agent].instructions.includes(marker);
  })) {
    error = 'The compiled instructions do not match the enabled skill metadata.';
  }

  return {
    json: {
      valid: error === null,
      ...(error
        ? { response: { ok: false, error: { code: 'INVALID_SKILL_BUNDLE', message: error } } }
        : {
            configKey: 'enabledSkills',
            value: JSON.stringify({
              schemaVersion: 2,
              enabledSkills,
              globalInstructions,
              agents,
              sourceHash,
            }),
            sourceHash,
            response: {
              ok: true,
              enabledSkills: enabledSkills.map((skill) => skill.id),
              sourceHash,
            },
          }),
    },
  };

const validation = $('Validate Skill Bundle').first().json;
if (!validation.valid) {
  return { json: validation.response };
}
if (!Number.isInteger($json.id)) {
  return {
    json: {
      ok: false,
      error: {
        code: 'SKILL_SYNC_UNAVAILABLE',
        message: 'Enabled skills could not be saved. Rerun the skill sync helper.'
      }
    }
  };
}
return { json: validation.response };
